insert into public.sources (id, title, publisher, url, rights, review_status) values
  ('e30-owner-handbook', 'BMW 325i / 325is owner’s handbook', 'BMW of North America',
insert into e30_guide_snapshots (revision, content) values
  ('fd15e381818ac2d2293b77e0', '{"slug":"e30-coolant-bleeding","title":"Fill and bleed the M20 cooling system","system":"cooling","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"30–60 min plus cool-down","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"Late rear-wheel-drive E30 325i with the original M20B25 and its separate expansion tank.","reviewStatus":"draft","sourceChecked":true,"applicability":"Late rear-wheel-drive E30 325i with the original M20B25 and its separate expansion tank.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"17-6 · 17 00 039 and late tank on 17-8/1","pdfPages":[332,337]},"evidence":[{"label":"BMW · 17-6, bleeding the M20 cooling system","href":"/manual/17?pdf=332"},{"label":"BMW · 17-8/1, late expansion-tank cold level","href":"/manual/17?pdf=337"},{"label":"1991 325i coupe · expansion tank diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/cooling_exhaust_system/expansion_tank.html"}],"tools":["8 mm wrench for the original thermostat-housing bleed screw.","Low-range torque wrench, clean funnel and drain pan."],"cautions":["Wait for the engine and coolant to cool completely before opening the system. Catch the coolant and keep it away from children and animals.","Stop the engine if the temperature rises abnormally, coolant escapes, or cabin heat drops out when the engine is warm."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Fresh coolant approved for the installed engine, mixed to the required concentration."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"17-6 · 17 00 039 and late tank on 17-8/1","pdf":332,"href":"/manual/17?pdf=332"}},{"number":2,"tools":[],"source":{"printed":"17-6 · 17 00 039 and late tank on 17-8/1","pdf":332,"href":"/manual/17?pdf=332"}},{"number":3,"tools":[],"source":{"printed":"17-6 · 17 00 039 and late tank on 17-8/1","pdf":337,"href":"/manual/17?pdf=337"}}]},"steps":[{"title":"Open the cold system","body":"With the engine off, set the heater to hot. Open the separate expansion tank and loosen the 8 mm thermostat-housing bleed screw.","check":"The open bleeder is at the M20 thermostat housing."},{"title":"Fill slowly and close the bleeder","body":"Pour into the expansion tank until a steady, bubble-free stream reaches the bleed point. Close the original bleeder at 8 Nm. Set the cold level to the molded mark and install the cap.","check":"The bleeder and cap are seated and the tank is at its cold mark."},{"title":"Warm, cool and check again","body":"Run in a well-ventilated area and monitor the gauge and cabin heat. Shut down and let everything cool fully. Recheck the level at about 20 °C and inspect the joints and bleed screw for leaks.","check":"The cold level is stable and there is no leak or overheating."}]}'::jsonb),
  ('4cc811d2e2e97b5524e4b573', '{"slug":"e30-radiator","title":"Replace the late M20 manual radiator","system":"cooling","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"1–2 hr plus cool-down","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"Late rear-wheel-drive E30 325i with the original M20B25 and manual transmission. Check A/C equipment before matching the radiator and thermoswitch.","reviewStatus":"draft","sourceChecked":true,"applicability":"Late rear-wheel-drive E30 325i with the original M20B25 and manual transmission. Check A/C equipment before matching the radiator and thermoswitch.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"17-7 to 17-7/1 · 17 11 000","pdfPages":[333,334]},"relatedGuides":["e30-coolant-bleeding","e30-expansion-tank"],"evidence":[{"label":"BMW · 17-7, radiator removal and installation","href":"/manual/17?pdf=333"},{"label":"BMW · 17-7/1, late radiator and drain position","href":"/manual/17?pdf=334"},{"label":"1991 325i coupe · radiator and supports diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/cooling_exhaust_system/radiator_frame.html"}],"tools":["10 mm socket for an original M6 hex-head mount. Use the drive profile supplied with the actual drain plug.","Low-range torque wrench covering 2.5–10 Nm, clamp driver, catch pan and gloves."],"cautions":["Wait for the engine and coolant to cool completely before opening the system. Catch the coolant and keep it away from children and animals.","This procedure covers the manual-transmission radiator. An automatic has separate cooler lines and requires an ATF level check."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Radiator for the late manual 325i, approved coolant and any failed mounts or hose clamps."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"17-7 to 17-7/1 · 17 11 000","pdf":333,"href":"/manual/17?pdf=333"}},{"number":2,"tools":[],"source":{"printed":"17-7 to 17-7/1 · 17 11 000","pdf":334,"href":"/manual/17?pdf=334"}},{"number":3,"tools":[],"source":{"printed":"17-7 to 17-7/1 · 17 11 000","pdf":334,"href":"/manual/17?pdf=334"}}]},"steps":[{"title":"Drain and free the shroud","body":"Disconnect the battery ground. Catch the coolant at the lower drain. Release the shroud retainers and lift or park the shroud as the manual shows. Disconnect the hoses and any temperature-switch plug.","check":"The radiator can move without pulling hoses or wiring."},{"title":"Lift the radiator and transfer hardware","body":"Remove the upper mounting hardware. Lift the radiator out of its rubber supports. Check the supports, shroud, drain plug and any used temperature-switch seal before transferring hardware.","check":"The replacement core and lower locating pegs match the original."},{"title":"Fit, refill and leak-check","body":"Seat the radiator on its supports. Tighten the original M6 mount to 10 Nm and the catalog-style drain plug to 2.5 Nm. Reconnect the switch, hoses and shroud. Follow the M20 fill and bleed guide before checking for leaks and fan clearance.","check":"The housing is supported and the fan turns without shroud contact."}]}'::jsonb),
  ('9a44b2be4c1f0a87e772db4a', '{"slug":"e30-expansion-tank","title":"Replace the late M20 expansion tank","system":"cooling","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"30–60 min plus cool-down","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"Late rear-wheel-drive E30 325i with the original M20B25 and clip-mounted tank from 09/1987.","reviewStatus":"draft","sourceChecked":true,"applicability":"Late rear-wheel-drive E30 325i with the original M20B25 and clip-mounted tank from 09/1987.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"17-8/1 · 17 11 100","pdfPages":[337]},"relatedGuides":["e30-coolant-bleeding"],"evidence":[{"label":"BMW · 17-8/1, 1988-on expansion tank","href":"/manual/17?pdf=337"},{"label":"1991 325i coupe · expansion tank diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/cooling_exhaust_system/expansion_tank.html"}],"tools":["30 mm wrench for the original level switch.","Low-range torque wrench, clamp driver, 8 mm bleeder wrench and drain pan."],"cautions":["Wait for the engine and coolant to cool completely before opening the system. Catch the coolant and keep it away from children and animals.","Match the late separate tank and all three hose connections before removing the old tank."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Late expansion tank, correct level-switch seal, coolant and replacement clamps for the opened connections."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"17-8/1 · 17 11 100","pdf":337,"href":"/manual/17?pdf=337"}},{"number":2,"tools":[],"source":{"printed":"17-8/1 · 17 11 100","pdf":337,"href":"/manual/17?pdf=337"}},{"number":3,"tools":[],"source":{"printed":"17-8/1 · 17 11 100","pdf":337,"href":"/manual/17?pdf=337"}}]},"steps":[{"title":"Drain to below the tank","body":"Open the cold cap and catch the coolant. Unplug the level switch and label the lower hoses and small vent line before disconnecting them.","check":"Each hose is identified and isolated clear of the mount."},{"title":"Transfer the switch and fit the tank","body":"Unclip the tank from its bracket. With a new seal, tighten the original 30 mm wrench-size level switch to 3 Nm. Engage the replacement tank in all bracket clips and reconnect the original hose routing.","check":"The tank is secure and each hose is fully seated without a kink."},{"title":"Refill and verify","body":"Bleed at the M20 thermostat housing, then recheck the level at about 20 °C. Inspect the tank seams, hose joints and switch seal and check for a low-level warning.","check":"The joint surfaces are dry and the level is stable."}]}'::jsonb),
  ('9462db52b82fcb5bb73d91fd', '{"slug":"e30-m20-timing-belt","title":"M20 timing belt and tensioner","system":"engine","engines":["M20"],"level":"Advanced","kind":"replacement","duration":"3–5 hr","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"1991 U.S. 325i coupe, M20, rear-wheel drive. Confirm the fitted sprocket profile and matched roller. The M40 procedure is separate.","reviewStatus":"draft","sourceChecked":true,"applicability":"1991 U.S. 325i coupe, M20, rear-wheel drive. Confirm the fitted sprocket profile and matched roller. The M40 procedure is separate.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"11-66a to 11-66b · 11 31 110","pdfPages":[110,111]},"relatedGuides":["e30-radiator","e30-coolant-bleeding"],"evidence":[{"label":"BMW · 11-66a, M20 timing belt","href":"/manual/11?pdf=110"},{"label":"BMW · 11-66b, timing marks and belt profile","href":"/manual/11?pdf=111"},{"label":"Continental · M20 timing belt and special tools","href":"https://www.showmethepartsdb3.com/BIN/documents/Continental%20Elite/tb131k1a.pdf"},{"label":"1991 325i coupe · timing parts diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/engine/timing_and_valve_train_tooth_belt.html"}],"tools":["BMW 11 2 150 crankshaft hub holder if the hub is removed. Consult the full procedure before disturbing the hub.","32 mm fan-clutch wrench and pulley holder for the original left-hand coupling."],"cautions":["Wait for the engine and coolant to cool completely before opening the system. Catch the coolant and keep it away from children and animals.","Keep the crank and cam timed together. Stop if the marks disagree, a sprocket profile is uncertain, or the engine binds by hand."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Matching 127-tooth semicircular belt and tensioner for the late M20B25. Inspect the spring and plunger."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"11-66a to 11-66b · 11 31 110","pdf":110,"href":"/manual/11?pdf=110"}},{"number":2,"tools":[],"source":{"printed":"11-66a to 11-66b · 11 31 110","pdf":111,"href":"/manual/11?pdf=111"}},{"number":3,"tools":[],"source":{"printed":"11-66a to 11-66b · 11 31 110","pdf":111,"href":"/manual/11?pdf=111"}},{"number":4,"tools":[],"source":{"printed":"11-66a to 11-66b · 11 31 110","pdf":110,"href":"/manual/11?pdf=110"}}]},"steps":[{"title":"Clear the front of the engine","body":"Use the referenced coolant and belt access procedures to remove the radiator, viscous fan, accessory belts, pump pulley, distributor components and timing covers. Retain the crank sensor and damper orientation. If hub removal is needed, use the BMW hub holder and separate tightening procedure.","check":"The cam and crank timing marks are visible."},{"title":"Set number one to compression TDC","body":"Turn the crankshaft in the normal direction by hand. Verify both marks. Retract the tensioner against its spring and lock it in that position with the bolt indicated in the BMW drawing. Remove the old belt without moving either shaft.","check":"Both marks remain aligned and the late sprockets match the new belt."},{"title":"Fit and tension the new belt","body":"Route the belt from crank to intermediate shaft to cam, then around the tensioner. Keep slack at the tensioner. Release the roller and rotate the crank slowly through two turns. Verify both marks and tighten the two tensioner bolts to the belt maker’s 16 lb-ft (about 22 Nm), in the specified order.","check":"The marks return to alignment with no binding."},{"title":"Refit and check","body":"Refit the covers, sensor, distributor and front drive in their original positions. Restore the cooling system and verify that wiring and hoses clear all moving parts before starting.","check":"Coolant is bled, the engine runs smoothly, and the covers and lines are secure."}]}'::jsonb),
  ('a043597738e2ccb9867cb697', '{"slug":"e30-clutch-bleeding","title":"Bleed the clutch hydraulics","system":"drivetrain","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"30–60 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"Late rear-wheel-drive E30 325i with the original M20B25 and hydraulic clutch on the manual transmission.","reviewStatus":"draft","sourceChecked":true,"applicability":"Late rear-wheel-drive E30 325i with the original M20B25 and hydraulic clutch on the manual transmission.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"21-1 · 21 00 006","pdfPages":[358]},"evidence":[{"label":"BMW · 21-1, clutch bleeding","href":"/manual/21?pdf=358"},{"label":"1991 325i coupe · clutch cylinder and vent screw diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/gearshift_clutch/clutch_control.html"}],"tools":["Reservoir pressure bleeder with the fitted cap adapter, clear hose and fluid bottle. Match the six-point wrench to the installed vent screw."],"cautions":["Chock the wheels and use a rated lift or stands. Keep the removed assembly supported separately.","Brake fluid damages paint. Keep the shared reservoir supplied. Never press the pedal while the slave cylinder is detached."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Fresh brake fluid approved for the clutch hydraulics."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"21-1 · 21 00 006","pdf":358,"href":"/manual/21?pdf=358"}},{"number":2,"tools":[],"source":{"printed":"21-1 · 21 00 006","pdf":358,"href":"/manual/21?pdf=358"}},{"number":3,"tools":[],"source":{"printed":"21-1 · 21 00 006","pdf":358,"href":"/manual/21?pdf=358"}}]},"steps":[{"title":"Prepare the reservoir","body":"Inspect the slave and feed for leaks. Fit the pressure-bleeder adapter and support the car with safe access to the transmission.","check":"The reservoir is supplied and the adapter seals."},{"title":"Purge the slave cylinder","body":"Attach the clear hose and open the fitted bleed screw. Work the pedal as shown while fluid runs into the bottle. Close the bleeder when the stream is free of bubbles.","check":"The bleeder is closed and no air is visible in the hose."},{"title":"Verify release travel","body":"Depressurize the bleeder, restore the reservoir cap and check the pedal. If air remains after repeating the procedure, follow BMW’s detached-slave step with the piston controlled. Do not use the pedal during that step.","check":"The clutch disengages consistently and all hydraulic connections stay dry."}]}'::jsonb),
  ('5741b8f719347ac33e854122', '{"slug":"e30-driveshaft-flex-disc","title":"Replace the driveshaft flex disc","system":"drivetrain","engines":["M20"],"level":"Advanced","kind":"replacement","duration":"2–4 hr","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"Late rear-wheel-drive E30 325i with the original M20B25 and Getrag 260. Match the flange diameter and bolt grade before choosing hardware.","reviewStatus":"draft","sourceChecked":true,"applicability":"Late rear-wheel-drive E30 325i with the original M20B25 and Getrag 260. Match the flange diameter and bolt grade before choosing hardware.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"26-6 · 26 11 051","pdfPages":[459,460]},"relatedGuides":["e30-driveshaft-center-support"],"evidence":[{"label":"BMW · 26-6, flex disc replacement","href":"/manual/26?pdf=459"},{"label":"BMW · 26-6, flex disc orientation and preload","href":"/manual/26?pdf=460"},{"label":"1991 325i coupe · driveshaft and flex disc diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/steering_drive_shaft/drive_shaft_universal_joint_centre_mounting.html"}],"tools":["BMW 26 1 040 for the sliding ring; socket and counterhold for fitted flange bolts. Use 17 mm for standard M10 hex heads when fitted and verify the actual tool fit.","Rated exhaust and shaft supports, torque wrench, and a ruler for 4–6 mm preload."],"cautions":["Chock the wheels and use a rated lift or stands. Keep the removed assembly supported separately.","Let the exhaust cool. Support the shaft, keep its halves indexed and keep its weight off the fuel crossover line. This guide covers the Getrag 260 layout."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Flex disc for the fitted flange, matching bolts and new self-locking nuts."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"26-6 · 26 11 051","pdf":459,"href":"/manual/26?pdf=459"}},{"number":2,"tools":[],"source":{"printed":"26-6 · 26 11 051","pdf":460,"href":"/manual/26?pdf=460"}},{"number":3,"tools":[],"source":{"printed":"26-6 · 26 11 051","pdf":460,"href":"/manual/26?pdf=460"}}]},"steps":[{"title":"Expose and support the shaft","body":"Remove the required exhaust sections and heat shields. Mark the flange and shaft orientation. Use BMW 26 1 040 to loosen the sliding joint ring.","check":"The shaft and exhaust are supported with the oxygen sensor lead and fuel lines clear."},{"title":"Replace the coupling","body":"Release the transmission flange and support bracket. Move the shaft far enough to clear the centering pin without separating its halves. Install the new disc with the molded arrows toward the flange arms.","check":"Every arrow points to the corresponding flange and the bolts retain their specified orientation."},{"title":"Set preload and torque","body":"Check the centering pilot. Use the torque row for the marked M10 bolt grade. Preload the support 4–6 mm toward the front and tighten its fasteners to 21 Nm. Tighten the fitted RWD sliding ring to 10 Nm after the shaft is installed.","check":"The support is preloaded, the coupling is seated, and the shaft turns freely."}]}'::jsonb),
  ('37f6ce15607f7b67b5fbdfc6', '{"slug":"e30-rear-shock-absorbers","title":"Rear shocks and upper mounts","system":"suspension","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"1–2 hr per axle","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"1991 U.S. 325i coupe, M20, rear-wheel drive. Conventional rear shocks, without ride-height control.","reviewStatus":"draft","sourceChecked":true,"applicability":"1991 U.S. 325i coupe, M20, rear-wheel drive. Conventional rear shocks, without ride-height control.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"33-16 · 33 52 000","pdfPages":[636]},"evidence":[{"label":"BMW · 33-16, rear shock replacement","href":"/manual/33?pdf=636"},{"label":"BMW TIS 33 52 · Rear shock tightening table","href":"https://workshop-manuals.com/bmw/3_series_e30/325e_m20_sal/4_tightening_torques/33__rear_axle/52__shock_absorber/1_azd__shock_absorbers/"},{"label":"U.S. 325i · shock and mount diagram","href":"https://www.realoem.com/bmw/enUS/showparts?diagId=33_0327&id=1123-USA---E30-BMW-325i"}],"tools":["Support jack for the trailing arm and rated stands.","Piston-rod counterhold for the fitted shock; size depends on the shaft."],"cautions":["Chock the wheels and use a rated lift or stands. Keep the removed assembly supported separately.","The shock limits trailing-arm droop. Support the arm before undoing the lower bolt and confirm its grade before tightening."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Matched rear shocks or upper mounts as needed, new upper gaskets and applicable self-locking nuts."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"33-16 · 33 52 000","pdf":636,"href":"/manual/33?pdf=636"}},{"number":2,"tools":[],"source":{"printed":"33-16 · 33 52 000","pdf":636,"href":"/manual/33?pdf=636"}},{"number":3,"tools":[],"source":{"printed":"33-16 · 33 52 000","pdf":636,"href":"/manual/33?pdf=636"}}]},"steps":[{"title":"Expose the mount and support the arm","body":"Move aside trunk trim. Support the semi-trailing arm before releasing the lower shock bolt. Protect nearby brake hoses and body trim.","check":"The trailing arm remains supported as the shock is unloaded."},{"title":"Change the shock or upper mount","body":"Remove the upper mount fasteners and withdraw the shock. Replace the gasket. If reusing the mount, inspect its rubber and tighten the original shaft nut to 15 Nm with the correct counterhold. Prime dampers only as their manufacturer specifies.","check":"The gasket sits flat and the mount has no torn rubber or looseness."},{"title":"Tighten at installed height","body":"Tighten the upper M8 fasteners to 22 Nm. Bring the arm to normal ride position and use the confirmed lower-bolt specification for its grade and source.","check":"The hardware is secure, the arm moves freely, and the trim is refitted."}]}'::jsonb),
  ('b2f82aaafa71d7204a2c8bd5', '{"slug":"e30-handbrake-adjustment","title":"Adjust the rear-disc parking brake","system":"brakes","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"30–60 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"Rear-wheel-drive E30 with the separate shoes inside the rear rotor hats. Rear drum versions use their own adjustment.","reviewStatus":"draft","sourceChecked":true,"applicability":"Rear-wheel-drive E30 with the separate shoes inside the rear rotor hats. Rear drum versions use their own adjustment.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"34-3 · 34 10 014","pdfPages":[642]},"evidence":[{"label":"BMW · 34-3, parking brake adjustment","href":"/manual/34?pdf=642"},{"label":"1991 325i coupe · parking brake shoe diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/brakes_pedals/parking_brake_brake_shoes.html"}],"tools":["Slotted screwdriver that reaches through the wheel bolt hole, spanners matched to the cable nuts, and a wheel socket and torque wrench."],"cautions":["Chock the wheels and use a rated lift or stands. Keep the removed assembly supported separately.","This is the disc-brake layout with small shoes inside the rear rotor hats. Repair a seized cable or contaminated shoe before adjusting."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":[],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"34-3 · 34 10 014","pdf":642,"href":"/manual/34?pdf=642"}},{"number":2,"tools":[],"source":{"printed":"34-3 · 34 10 014","pdf":642,"href":"/manual/34?pdf=642"}},{"number":3,"tools":[],"source":{"printed":"34-3 · 34 10 014","pdf":642,"href":"/manual/34?pdf=642"}}]},"steps":[{"title":"Back off the cables","body":"Release the parking brake fully. Check that both cables move freely. Lift the lever boot and loosen the cable adjusting nuts so the shoes can settle.","check":"Both rear wheels turn with the brake released."},{"title":"Adjust each shoe set at the rotor","body":"Remove one wheel bolt per side. Rotate the access hole about 30° rearward of vertical. Use a flat screwdriver to expand the shoes until the rotor locks, then back off three or four adjuster teeth.","check":"Each rotor turns easily with the lever released."},{"title":"Balance the cables","body":"Raise the lever five clicks. Adjust both cable nuts until both wheels just turn with even resistance. Release the lever and check free rotation and warning switch operation. Refit the original wheel bolts and torque to 110 Nm.","check":"Both sides hold and release evenly."}]}'::jsonb),
  ('c618492d0afea230d867cf0c', '{"slug":"e30-parking-brake-shoes","title":"Replace the rear-disc parking brake shoes","system":"brakes","engines":["M20"],"level":"Advanced","kind":"replacement","duration":"1–2 hr per axle","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"E30 325i with the original rear disc and internal parking-brake shoes.","reviewStatus":"draft","sourceChecked":true,"applicability":"E30 325i with the original rear disc and internal parking-brake shoes.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"34-17 · 34 41 200","pdfPages":[649,660,642]},"relatedGuides":["e30-rear-brake-pads-discs","e30-handbrake-adjustment"],"evidence":[{"label":"BMW · 34-17, parking brake shoe replacement","href":"/manual/34?pdf=660"},{"label":"BMW · 34-3, parking brake adjustment","href":"/manual/34?pdf=642"},{"label":"BMW · 34-9, rear disc removal","href":"/manual/34?pdf=649"},{"label":"1991 325i coupe · parking brake shoe diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/brakes_pedals/parking_brake_brake_shoes.html"}],"tools":["BMW 34 4 000 spring-retainer tool. Use the rear brake procedure for the 7 mm hex guide bolts, caliper hanger and rotor fasteners."],"cautions":["Chock the wheels and use a rated lift or stands. Keep the removed assembly supported separately.","Avoid inhaling brake dust. Keep friction surfaces clean and verify the brake works before road use."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Matched parking brake shoes for both rear rotors. Replace damaged retainers, springs or adjusters."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"34-17 · 34 41 200","pdf":649,"href":"/manual/34?pdf=649"}},{"number":2,"tools":[],"source":{"printed":"34-17 · 34 41 200","pdf":660,"href":"/manual/34?pdf=660"}},{"number":3,"tools":[],"source":{"printed":"34-17 · 34 41 200","pdf":642,"href":"/manual/34?pdf=642"}}]},"steps":[{"title":"Expose the shoe hardware","body":"Release the cables and remove both rear brake discs using the rear brake guide. Support the calipers independently of the hoses. Compare the drum surfaces and shoe layout before removing anything.","check":"The rotor hats are serviceable and both sets of hardware can be compared."},{"title":"Replace and orient the shoes","body":"Unhook the return springs. Use BMW 34 4 000 to turn and release the spring retainers. Refit the shoes, expansion lock, adjuster and springs in their illustrated positions.","check":"All retainers are locked and each shoe moves without binding."},{"title":"Refit and adjust","body":"Reinstall the rear discs and tighten their retaining screws to 16 Nm. Refit the calipers with the applicable torques in the rear brake guide. Set shoe clearance and balance the cables using 34 10 014.","check":"The parking brake holds evenly, releases fully, and the foot pedal is firm."}]}'::jsonb),
  ('fba9acd1b7e871dffebeb53e', '{"slug":"e30-sunroof-alignment","title":"Align the steel sunroof panel","system":"body","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"45–90 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"E30 factory sliding and tilting steel sunroof with the guide and gate shown in BMW 54 12 004.","reviewStatus":"draft","sourceChecked":true,"applicability":"E30 factory sliding and tilting steel sunroof with the guide and gate shown in BMW 54 12 004.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"54-1 · 54 12 004","pdfPages":[1057]},"evidence":[{"label":"BMW · 54-1, panel height and adjustment","href":"/manual/54?pdf=1057"}],"tools":["Two 4 mm keys for the guide locks, BMW 00 2 102/103 for the adjusters, straightedge, 0.2 mm plastic gauge and low-range torque wrench."],"cautions":["Keep fingers clear of the opening. Stop if the guides are damaged or a seized cable prevents both sides from reaching the closed position together."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["New self-locking panel screws for the six fasteners removed or loosened for adjustment."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"54-1 · 54 12 004","pdf":1057,"href":"/manual/54?pdf=1057"}},{"number":2,"tools":[],"source":{"printed":"54-1 · 54 12 004","pdf":1057,"href":"/manual/54?pdf=1057"}},{"number":3,"tools":[],"source":{"printed":"54-1 · 54 12 004","pdf":1057,"href":"/manual/54?pdf=1057"}}]},"steps":[{"title":"Free the liner and close the panel","body":"Open the roof about 50 mm and release the front liner frame. Close the lid and slide the liner back. Lock the left and right guides at the closed position with 4 mm keys as shown.","check":"Both guides are at position zero and the liner is out of the way."},{"title":"Set height and gap","body":"Use BMW 00 2 102/103 to loosen the three adjusters per side. With a straightedge, set the front edge 1 mm below the roof and the rear edge 1 mm above. Compare the front and rear gaps with a plastic gauge.","check":"Panel height and spacing match the factory drawing and the seal is even."},{"title":"Secure and cycle","body":"Set new self-locking screws to 3.5 Nm. Remove both locking keys. Reclip the liner as BMW shows and check that the roof slides, tilts and closes without contacting paint or trim.","check":"The panel is seated and the closed position repeats."}]}'::jsonb),
  ('f5041bce229c8fd314992be9', '{"slug":"e30-heater-blower","title":"Replace the heater blower motor","system":"climate","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"45–90 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"E30 cowl-access blower shown in BMW 64 11 210. Match the motor code and housing before buying.","reviewStatus":"draft","sourceChecked":true,"applicability":"E30 cowl-access blower shown in BMW 64 11 210. Match the motor code and housing before buying.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"64-9 · 64 11 210","pdfPages":[1205]},"evidence":[{"label":"BMW · 64-9, blower motor removal and code","href":"/manual/64?pdf=1205"},{"label":"1991 325i coupe · heater core, valves and blower diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/heater_and_air_conditioning/heater_radiator_blower.html"}],"tools":["Fastener driver matched to the cowl access panel, trim tool and side cutters for the original loom tie."],"cautions":["Switch off the ignition and disconnect the battery ground before disconnecting the wiring.","Keep the wheels and motor as a balanced assembly. Protect the air flap and keep hands out of the fan when power is restored."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Balanced motor and fan-wheel assembly matched to the installed housing."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"64-9 · 64 11 210","pdf":1205,"href":"/manual/64?pdf=1205"}},{"number":2,"tools":[],"source":{"printed":"64-9 · 64 11 210","pdf":1205,"href":"/manual/64?pdf=1205"}},{"number":3,"tools":[],"source":{"printed":"64-9 · 64 11 210","pdf":1205,"href":"/manual/64?pdf=1205"}}]},"steps":[{"title":"Open the cowl access","body":"Lift the cowl seal. Release the loom fastener without cutting wires, then move the access cover aside. Release both heater-cover retaining straps.","check":"The blower is accessible and the loom is supported."},{"title":"Remove and match the assembly","body":"Photograph and unplug the two motor leads. Release the center clamp, then lift the motor and both fans clear of the air flap. Match the original housing and motor code.","check":"Both wheels are intact and the replacement drops into the same supports."},{"title":"Check spin and refit","body":"Clamp the motor in place and check that the wheels turn freely by hand. Restore the connectors, access covers, seal and loom tie. Reconnect the battery and check every fan speed.","check":"The blower runs without scraping or excessive vibration."}]}'::jsonb),
  ('698fb4f4790dd5fd4d2a7964', '{"slug":"e30-blower-resistor","title":"Replace the heater blower resistor","system":"climate","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"30–60 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"E30 cowl-access resistor plate shown in BMW 64 11 220. Check its connector and fitted housing.","reviewStatus":"draft","sourceChecked":true,"applicability":"E30 cowl-access resistor plate shown in BMW 64 11 220. Check its connector and fitted housing.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"64-11 · 64 11 220","pdfPages":[1206]},"evidence":[{"label":"BMW · 64-11, blower resistor access","href":"/manual/64?pdf=1206"},{"label":"1991 325i coupe · heater core, valves and blower diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/heater_and_air_conditioning/heater_radiator_blower.html"}],"tools":["Driver for the actual cowl cover screws, trim tool and cutters for the original loom tie."],"cautions":["Switch off the ignition and disconnect the battery ground before disconnecting the wiring.","A resistor runs hot. Check for a stiff blower, restricted air path or melted connector before replacing the resistor alone."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Resistor plate matched to the installed blower housing and connector."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"64-11 · 64 11 220","pdf":1206,"href":"/manual/64?pdf=1206"}},{"number":2,"tools":[],"source":{"printed":"64-11 · 64 11 220","pdf":1206,"href":"/manual/64?pdf=1206"}},{"number":3,"tools":[],"source":{"printed":"64-11 · 64 11 220","pdf":1206,"href":"/manual/64?pdf=1206"}}]},"steps":[{"title":"Access the resistor plate","body":"Pull back the cowl seal, free the harness tie and move the access panel. Release the retaining straps and find the resistor plate in its illustrated air passage.","check":"The plate and connector can move without pulling on the loom."},{"title":"Inspect and replace","body":"Pull the plate out of its socket. Inspect for heat damage, debris and a binding blower wheel. Fit the matching plate fully in its cooling-air position.","check":"The connector is firm and the resistor is flush in the duct."},{"title":"Restore covers and test","body":"Secure the cowl cover and seal, reconnect the battery, then test every speed. Stop if the connector heats, smells burnt or the fan slows unexpectedly.","check":"Each fan setting works and air reaches the vents."}]}'::jsonb),
  ('5bdb5a90eee5004f1aa0fb9e', '{"slug":"e30-heater-valve","title":"Replace the heater water valve","system":"climate","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"1–2 hr plus cool-down","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"Left-hand-drive E30 325i with the valve and pipe joints shown in BMW 64 11 271.","reviewStatus":"draft","sourceChecked":true,"applicability":"Left-hand-drive E30 325i with the valve and pipe joints shown in BMW 64 11 271.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"64-12 · 64 11 271","pdfPages":[1207,332]},"relatedGuides":["e30-coolant-bleeding"],"evidence":[{"label":"BMW · 64-12, heater valve and seal","href":"/manual/64?pdf=1207"},{"label":"1991 325i coupe · heater core, valves and blower diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/heater_and_air_conditioning/heater_radiator_blower.html"}],"tools":["Trim driver, clamp driver, short socket or driver matched to the valve joint and an 8 mm wrench for the original M20 bleeder."],"cautions":["Wait for the engine and coolant to cool completely before opening the system. Catch the coolant and keep it away from children and animals.","Switch off the ignition and disconnect the battery ground before disconnecting the wiring."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Heater water valve and new pipe seals for the installed heater box."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"64-12 · 64 11 271","pdf":1207,"href":"/manual/64?pdf=1207"}},{"number":2,"tools":[],"source":{"printed":"64-12 · 64 11 271","pdf":1207,"href":"/manual/64?pdf=1207"}},{"number":3,"tools":[],"source":{"printed":"64-12 · 64 11 271","pdf":332,"href":"/manual/17?pdf=332"}}]},"steps":[{"title":"Expose the valve and catch coolant","body":"Remove the left lower dash trim and tray as shown. Drain coolant, protect the carpet and trace the heater hoses and valve connector before disconnecting them.","check":"The valve is accessible and any runoff is captured."},{"title":"Unfasten and replace the valve","body":"Unplug the valve, release its clamp and unfasten the pipe joints without flexing the pipes. Renew the valve seal and seat each pipe squarely before securing it.","check":"The pipe joints line up and the wiring is clear of moving pedals."},{"title":"Bleed and check operation","body":"Reconnect the hoses and electrical plug. Refill and bleed the cooling system. Check for leaks behind the trim and confirm the controls can change cabin air temperature.","check":"The valve and pipe joints are dry before the trim goes back."}]}'::jsonb),
  ('2ef6baeafc5162d05bfc177f', '{"slug":"e30-heater-core","title":"Replace the heater core","system":"climate","engines":["M20"],"level":"Advanced","kind":"replacement","duration":"2–4 hr plus cool-down","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"Left-hand-drive E30 325i with the heater case and footwell pipe routing in BMW 64 11 531.","reviewStatus":"draft","sourceChecked":true,"applicability":"Left-hand-drive E30 325i with the heater case and footwell pipe routing in BMW 64 11 531.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"64-14 · 64 11 531","pdfPages":[1210,332]},"relatedGuides":["e30-coolant-bleeding","e30-heater-valve"],"evidence":[{"label":"BMW · 64-14, heater core and pipe seals","href":"/manual/64?pdf=1210"},{"label":"1991 325i coupe · heater core, valves and blower diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/heater_and_air_conditioning/heater_radiator_blower.html"}],"tools":["Trim driver and short sockets or drivers matched to the pipe and core fasteners. Use an 8 mm wrench and low-range torque wrench for the M20 bleed screw."],"cautions":["Wait for the engine and coolant to cool completely before opening the system. Catch the coolant and keep it away from children and animals.","Switch off the ignition and disconnect the battery ground before disconnecting the wiring.","Cover the carpet and electrical connectors before opening any heater line."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Heater core and new pipe sealing rings for the installed heater box."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"64-14 · 64 11 531","pdf":1210,"href":"/manual/64?pdf=1210"}},{"number":2,"tools":[],"source":{"printed":"64-14 · 64 11 531","pdf":1210,"href":"/manual/64?pdf=1210"}},{"number":3,"tools":[],"source":{"printed":"64-14 · 64 11 531","pdf":332,"href":"/manual/17?pdf=332"}}]},"steps":[{"title":"Clear the driver-side access","body":"Remove the tray and lower dash panel. Drain and collect coolant. Free the heater duct connector and molded access piece in the order shown.","check":"The end of the core and both pipe connections are visible."},{"title":"Withdraw the core","body":"Support the coolant pipes while undoing their unions. Remove the core retaining bolts and slide the core straight out. Compare the flanges, orientation and seal seats against the replacement.","check":"The pipes and housing are undamaged and the seals match."},{"title":"Refill and leak-check before closing","body":"Slide the new core into the case and seat the new seals without forcing the pipes sideways. Refill and bleed the M20 system. Inspect the dry footwell and test the heater before installing the ducts and trim.","check":"Cabin heat is stable and the pipe joints and carpet remain dry."}]}'::jsonb),
  ('a44aac480ee9b346a65c0464', '{"slug":"e30-mirror-switch","title":"Replace the power-mirror switch","system":"electrical","engines":["M20"],"level":"Beginner","kind":"replacement","duration":"15–30 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"E30 with the door-mounted selector and adjustment switch shown in BMW 61 31 255.","reviewStatus":"draft","sourceChecked":true,"applicability":"E30 with the door-mounted selector and adjustment switch shown in BMW 61 31 255.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"61-7 · 61 31 255","pdfPages":[1146]},"evidence":[{"label":"BMW · 61-7, power mirror switch replacement","href":"/manual/61?pdf=1146"},{"label":"1991 325i coupe · outside mirror and switch diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/vehicle_trim/outside_mirror.html"}],"tools":["BMW 61 1 300 switch extractor or a non-marring tool that supports the switch edge."],"cautions":["Switch off the ignition and disconnect the battery ground before disconnecting the wiring.","Protect the door trim and hold the connector while unplugging the switch."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Mirror switch with the same connector and adjustment functions."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"61-7 · 61 31 255","pdf":1146,"href":"/manual/61?pdf=1146"}},{"number":2,"tools":[],"source":{"printed":"61-7 · 61 31 255","pdf":1146,"href":"/manual/61?pdf=1146"}},{"number":3,"tools":[],"source":{"printed":"61-7 · 61 31 255","pdf":1146,"href":"/manual/61?pdf=1146"}}]},"steps":[{"title":"Remove the control knob","body":"Protect the surrounding door trim and lift the adjustment knob as illustrated.","check":"The knob and switch bezel are intact."},{"title":"Lift out the switch","body":"Use BMW 61 1 300 or a matching non-marring trim tool. Support the plug and disconnect it by the housing. Compare the connector layout before attaching the replacement.","check":"The connector is fully seated and the harness remains inside the door opening."},{"title":"Refit and test both sides","body":"Snap the switch into the trim, refit the knob and restore the battery. Test the selector and movement of both mirrors.","check":"Each mirror moves in all four directions when selected."}]}'::jsonb),
  ('cd4db9ef45f4de122eb854b6', '{"slug":"e30-sealed-beam-headlight","title":"Replace a sealed-beam headlight insert","system":"electrical","engines":["M20"],"level":"Beginner","kind":"replacement","duration":"25–45 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"U.S. E30 325i with four sealed-beam lamps, the late arrangement cataloged from 06/1989.","reviewStatus":"draft","sourceChecked":true,"applicability":"U.S. E30 325i with four sealed-beam lamps, the late arrangement cataloged from 06/1989.","source":{"id":"e30-owner-handbook","title":"BMW 325i / 325is owner’s handbook","section":"BMW 325i handbook · p. 60","pdfPages":[]},"evidence":[{"label":"BMW 325i handbook · sealed-beam headlight installation, p. 60","href":"https://www.billswebspace.com/BMW%20E30%20Owner%20Manual%20%28325i-325is%29.pdf#page=61"},{"label":"Philips · U.S. 1990–91 325i lighting applications","href":"https://www.philips.com/c-dam/b2c/en_US/generic/support-home/support-page-product-flyers/automotive-lighting-tab-product-flyers/philips-classic-car-lighting-catalog-1946-2002.pdf"},{"label":"1991 325i coupe · late sealed-beam lamp diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/lighting/single_components_for_headlight.html"}],"tools":["Driver that seats in the grille and three clamping-ring screws. Proper beam-setting equipment for the aim check."],"cautions":["Switch off the ignition and disconnect the battery ground before disconnecting the wiring.","Stop if the connector shows heat damage or the lamp seat is broken. Have aim checked after refitting."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"df0694c579fdbd0e4e671675f510db3fc09fd136b70e4c034fea28c607a387f3","requiredParts":["Matching sealed-beam insert identified as outer low beam or inner high beam."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"BMW 325i handbook · sealed-beam headlight installation, p. 60","href":"https://www.billswebspace.com/BMW%20E30%20Owner%20Manual%20%28325i-325is%29.pdf#page=61"}},{"number":2,"tools":[],"source":{"printed":"BMW 325i handbook · sealed-beam headlight installation, p. 60","href":"https://www.billswebspace.com/BMW%20E30%20Owner%20Manual%20%28325i-325is%29.pdf#page=61"}},{"number":3,"tools":[],"source":{"printed":"BMW 325i handbook · sealed-beam headlight installation, p. 60","href":"https://www.billswebspace.com/BMW%20E30%20Owner%20Manual%20%28325i-325is%29.pdf#page=61"}}]},"steps":[{"title":"Identify the lamp","body":"Use the two outer inserts for low beam and the two inner inserts for high beam. Match the lens marking and connector on the failed unit.","check":"The replacement is the correct beam position and connector type."},{"title":"Release the clamping ring","body":"Remove the grille section and support the insert while loosening its three ring screws. Unplug the insert without disturbing the beam adjustment screws.","check":"The reflector carrier and adjusters have stayed in place."},{"title":"Seat and verify the lamp","body":"Engage the insert’s locating features and secure the ring and grille. Restore power and check both beam settings. Have the aiming pattern checked with the correct equipment.","check":"The lamp is seated firmly and lights in the correct switch position."}]}'::jsonb),
  ('c1d7a1494c88b82a41998c5c', '{"slug":"e30-fog-light-bulb","title":"Replace a late front fog light bulb","system":"electrical","engines":["M20"],"level":"Beginner","kind":"replacement","duration":"20–40 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"Late E30 with the 09/1987-on front housing that accepts the H3 bulb.","reviewStatus":"draft","sourceChecked":true,"applicability":"Late E30 with the 09/1987-on front housing that accepts the H3 bulb.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"63 99 201 · front fog lamp","pdfPages":[1191]},"evidence":[{"label":"BMW · 63 99 201, front fog bulb replacement","href":"/manual/63?pdf=1191"},{"label":"1991 325i coupe · late fog lamp diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/lighting/fog_lights.html"}],"tools":["Driver that fits the lamp frame retaining screws and a clean cloth for handling the bulb."],"cautions":["Switch off the ignition and disconnect the battery ground before disconnecting the wiring.","Let the lamp cool. Handle a halogen bulb by its base and protect the glass from scratches and fingerprints."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["H3 12 V 55 W bulb for the late catalog housing. Replace damaged seals as needed."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"63 99 201 · front fog lamp","pdf":1191,"href":"/manual/63?pdf=1191"}},{"number":2,"tools":[],"source":{"printed":"63 99 201 · front fog lamp","pdf":1191,"href":"/manual/63?pdf=1191"}},{"number":3,"tools":[],"source":{"printed":"63 99 201 · front fog lamp","pdf":1191,"href":"/manual/63?pdf=1191"}}]},"steps":[{"title":"Free the lamp housing","body":"Remove the retaining screws and withdraw the lamp from the holding frame shown in the manual. Support the housing by hand.","check":"The lamp is supported and the wiring has slack."},{"title":"Replace the bulb","body":"Disconnect the plug, open the rear cover and release the spring clip. Seat the H3 replacement with the same tab orientation before locking the clip.","check":"The bulb is flat in its seat and the lead is attached."},{"title":"Seal the lamp and test","body":"Check the seal, close the cover and reinstall the housing. Restore power and check the fog lights and their mounting angle.","check":"Both lamps work and the repaired housing is secure."}]}'::jsonb),
  ('3c0bce1cfaa10c4c02cab202', '{"slug":"e30-wiper-blades","title":"Replace the front wiper blades","system":"body","engines":["M20"],"level":"Beginner","kind":"replacement","duration":"10–20 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"E30 325i with original spring-latch front wiper arms. Match any replacement arm’s latch.","reviewStatus":"draft","sourceChecked":true,"applicability":"E30 325i with original spring-latch front wiper arms. Match any replacement arm’s latch.","source":{"id":"e30-owner-handbook","title":"BMW 325i / 325is owner’s handbook","section":"BMW 325i handbook · p. 59","pdfPages":[]},"evidence":[{"label":"BMW 325i handbook · front wiper blade removal, p. 59","href":"https://www.billswebspace.com/BMW%20E30%20Owner%20Manual%20%28325i-325is%29.pdf#page=60"},{"label":"1991 325i coupe · wiper arms and blades diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/vehicle_electrical_system/wiper_arm_wiper_blade.html"}],"tools":["Folded towel to protect the windshield and a ruler to verify both blade lengths."],"cautions":["Support the bare arm and protect the glass. Free frozen blades before operating the wipers."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"df0694c579fdbd0e4e671675f510db3fc09fd136b70e4c034fea28c607a387f3","requiredParts":["Two blades matched to the fitted arm latch. The standard pair is nominally 500 mm each."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"BMW 325i handbook · front wiper blade removal, p. 59","href":"https://www.billswebspace.com/BMW%20E30%20Owner%20Manual%20%28325i-325is%29.pdf#page=60"}},{"number":2,"tools":[],"source":{"printed":"BMW 325i handbook · front wiper blade removal, p. 59","href":"https://www.billswebspace.com/BMW%20E30%20Owner%20Manual%20%28325i-325is%29.pdf#page=60"}},{"number":3,"tools":[],"source":{"printed":"BMW 325i handbook · front wiper blade removal, p. 59","href":"https://www.billswebspace.com/BMW%20E30%20Owner%20Manual%20%28325i-325is%29.pdf#page=60"}}]},"steps":[{"title":"Match the replacement and protect the glass","body":"Check the two blade lengths and latch styles. Switch the wipers off at rest, then protect the windshield with a folded towel.","check":"Both replacements match their arm and the glass is covered."},{"title":"Release and fit one blade at a time","body":"Lift the arm away from the glass. Press the retaining spring, slide the old blade off and engage the replacement latch before lowering the arm.","check":"The new blade stays on when lightly pulled against the latch."},{"title":"Check sweep and park","body":"Wet the glass and run the wipers. Check the full sweep and parked position for interference with the trim and between the blades.","check":"Both blades park correctly and stay attached."}]}'::jsonb),
  ('d6cb429d9a2167fc98733195', '{"slug":"e30-power-steering-bleed","title":"Fill and bleed the power steering","system":"suspension","engines":["M20"],"level":"Intermediate","kind":"replacement","duration":"20–40 min","durationBasis":"Planning estimate for stock hardware in serviceable condition.","summary":"E30 with the hydraulic rack and dipstick-equipped reservoir in BMW 32 13 006.","reviewStatus":"draft","sourceChecked":true,"applicability":"E30 with the hydraulic rack and dipstick-equipped reservoir in BMW 32 13 006.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"32-6b · 32 13 006","pdfPages":[572]},"evidence":[{"label":"BMW · 32-6b, power steering filling and bleeding","href":"/manual/32?pdf=572"}],"tools":["Clean funnel, absorbent cloth and the reservoir dipstick."],"cautions":["Confirm the fluid on the reservoir label. Keep clear of belts, preserve the pump supply and avoid holding the steering at full lock."],"jobSupport":{"reviewedOn":"2026-11-16","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Hydraulic fluid specified for the fitted reservoir and system."],"conditionalParts":[],"stopConditions":[],"steps":[{"number":1,"tools":[],"source":{"printed":"32-6b · 32 13 006","pdf":572,"href":"/manual/32?pdf=572"}},{"number":2,"tools":[],"source":{"printed":"32-6b · 32 13 006","pdf":572,"href":"/manual/32?pdf=572"}},{"number":3,"tools":[],"source":{"printed":"32-6b · 32 13 006","pdf":572,"href":"/manual/32?pdf=572"}}]},"steps":[{"title":"Check the system before filling","body":"Identify the fluid and inspect the suction hose, return hose and rack connections for leaks. With the engine stopped, fill to the MAX mark on the dipstick.","check":"The fluid is correct and the pump feed stays covered."},{"title":"Cycle the steering","body":"Start the engine in a ventilated area. Sweep the steering toward each side twice without holding it at the stop. Shut off the engine and inspect the reservoir.","check":"Foaming and noise settle and the reservoir remains supplied."},{"title":"Recheck level and leaks","body":"With the engine off, correct the level to the reference mark. Check the disturbed joints and confirm normal assist without noise. If the fluid continues to foam, inspect the suction side for air entry.","check":"Fluid level stays stable and steering assist is even."}]}'::jsonb);
